package nl.smartstreamlabs.sbwdroneconfig;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import net.minecraft.core.*;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.*;
public class Ps01GeometryTest{
 private boolean blocked(Direction f,AABB nativeBox,int step){var actor=Shapes.create(Ps01Geometry.box(BlockPos.ZERO,f,nativeBox));for(int group=0;group<2;group++){var cells=group==0?Ps01Geometry.BODY:Ps01Geometry.DOOR;for(int i=0;i<cells.length;i++){var p=Ps01Geometry.cell(BlockPos.ZERO,f,cells[i]);if(Shapes.joinIsNotEmpty(actor,Ps01Geometry.collision(f,group==1,i,step).move(p.getX(),p.getY(),p.getZ()),BooleanOp.AND))return true;}}return false;}
 @Test public void actualDoorBlocksClosedAndReleasesAnOrdinaryOrCrawlingPlayerInEveryDirection(){for(var f:Direction.Plane.HORIZONTAL){assertTrue(blocked(f,new AABB(-.9,.26,-3.25,-.3,2.06,-2.65),0),f.toString());assertFalse(blocked(f,new AABB(-.9,.26,-3.25,-.3,2.06,-2.65),18),f.toString());assertFalse(blocked(f,new AABB(-.9,.26,-3.25,-.3,.86,-2.65),18));assertFalse(blocked(f,new AABB(-.3,.26,-.3,.3,2.06,.3),0),"The interior must be hollow");assertTrue(blocked(f,new AABB(1.65,.26,-.3,2.25,2.06,.3),18));}}
 @Test public void coverRequiresARealBarrierAndAnOpenDoorDoesNotDisableTheOtherWalls(){var front=new Vec3(-.6,1,-6);var victim=new Vec3(-.6,1,0);assertEquals(.72,Ps01Geometry.cover(front,victim,0,.8,.72),1e-7);assertEquals(0,Ps01Geometry.cover(front,victim,18,.8,.72),1e-7);assertEquals(.8,Ps01Geometry.cover(new Vec3(6,1,0),new Vec3(0,1,0),18,.8,.72),1e-7);assertEquals(.8,Ps01Geometry.cover(new Vec3(0,8,0),new Vec3(0,1,0),18,.8,.72),1e-7);assertEquals(0,Ps01Geometry.cover(new Vec3(4,1,-6),new Vec3(4,1,0),0,.8,.72));assertEquals(0,Ps01Geometry.cover(new Vec3(0,1,0),new Vec3(0,1,1),0,.8,.72));assertEquals(.4,Ps01Geometry.cover(new Vec3(6,1,0),victim,0,.4,.2),1e-7);}
 @Test public void nativeCoordinatesRoundTripWithoutAnotherUnitConversion(){var root=new BlockPos(123,60,-456);for(var f:Direction.Plane.HORIZONTAL){var p=Ps01Geometry.point(root,f,-1.2,2.3,3.4);var local=Ps01Geometry.local(root,f,p);assertEquals(-1.2,local.x,1e-9);assertEquals(2.3,local.y,1e-9);assertEquals(3.4,local.z,1e-9);for(var c:Ps01Geometry.DOOR)assertEquals(root,Ps01Geometry.root(Ps01Geometry.cell(root,f,c),f,c));}}
 @Test public void animationUsesTheSuppliedLinearClipAndHinge(){assertEquals(32,Ps01Geometry.DOOR_TICKS);assertEquals(0,Ps01Geometry.angle(0));assertEquals(45,Ps01Geometry.angle(.5f));assertEquals(90,Ps01Geometry.angle(1));assertArrayEquals(new double[]{-1.255,1.48,-2.995},Ps01Geometry.HINGE,1e-9);}
}
